// This state is intentionally limited to aggregate load facts. It is safe to
// expose in diagnostics because it never contains vault paths, note text, or
// shard names. `mode` distinguishes the startup-deferred path from a forced
// first-query load while the manifest/path metadata flags prove the order.
function emptySemanticIndexLoadTelemetry() {
  return {
    state: "idle",
    mode: "idle",
    manifestFirst: false,
    pathMetaAttempted: false,
    pathMetaLoaded: false,
    manifestRead: false,
    deferred: false,
    forced: false,
    shardCount: 0,
    shardsLoaded: 0,
    totalBytes: 0,
    largestBytes: 0,
    elapsedMs: 0,
    yields: 0,
    reads: 0,
    pathMetaReads: 0,
    completed: false,
    compatibilityState: "idle",
    compatibilityReason: "",
    compatibilityKey: "",
    error: ""
  };
}

function semanticIndexLoadTelemetrySnapshot(value = {}) {
  const base = emptySemanticIndexLoadTelemetry();
  const text = (input, max = 32) => singleLine(input || "").slice(0, max);
  const number = (input) => Math.max(0, Math.round(Number(input) || 0));
  return {
    state: text(value.state || base.state),
    mode: text(value.mode || base.mode),
    manifestFirst: Boolean(value.manifestFirst),
    pathMetaAttempted: Boolean(value.pathMetaAttempted),
    pathMetaLoaded: Boolean(value.pathMetaLoaded),
    manifestRead: Boolean(value.manifestRead),
    deferred: Boolean(value.deferred),
    forced: Boolean(value.forced),
    shardCount: number(value.shardCount),
    shardsLoaded: number(value.shardsLoaded),
    totalBytes: number(value.totalBytes),
    largestBytes: number(value.largestBytes),
    elapsedMs: number(value.elapsedMs),
    yields: number(value.yields),
    reads: number(value.reads),
    pathMetaReads: number(value.pathMetaReads),
    completed: Boolean(value.completed),
    compatibilityState: text(value.compatibilityState || base.compatibilityState),
    compatibilityReason: text(value.compatibilityReason || base.compatibilityReason, 120),
    compatibilityKey: text(value.compatibilityKey || base.compatibilityKey, 24),
    error: text(value.error, 240)
  };
}

function emptySemanticIndexCompatibilityRefresh() {
  return {
    state: "idle",
    key: "",
    reasonCode: "",
    reason: "",
    persistedGeneration: "",
    storageFingerprint: "",
    queuedAt: "",
    startedAt: "",
    completedAt: "",
    attempts: 0,
    error: ""
  };
}

function semanticIndexCompatibilityRefreshSnapshot(value = {}) {
  const base = emptySemanticIndexCompatibilityRefresh();
  const text = (input, max = 120) => singleLine(input || "").slice(0, max);
  const code = (input, max = 120) => text(input, max).replace(/[^a-z0-9._:-]+/gi, "-").replace(/^-+|-+$/g, "");
  return {
    state: text(value.state || base.state, 24),
    key: text(value.key || base.key, 24),
    reasonCode: code(value.reasonCode || base.reasonCode, 80),
    reason: code(value.reason || base.reason, 160),
    persistedGeneration: text(value.persistedGeneration || base.persistedGeneration, 80),
    storageFingerprint: text(value.storageFingerprint || base.storageFingerprint, 80),
    queuedAt: text(value.queuedAt || base.queuedAt, 40),
    startedAt: text(value.startedAt || base.startedAt, 40),
    completedAt: text(value.completedAt || base.completedAt, 40),
    attempts: Math.max(0, Math.round(Number(value.attempts) || 0)),
    error: code(value.error || base.error, 160)
  };
}

// Incremental/index-repair callers need one stable result shape while older
// provider-free fixtures still compare operation results to booleans. The
// non-enumerable valueOf keeps those compatibility assertions working without
// leaking functions into telemetry or persisted state.
function semanticOperationResult({ ok = false, changed = false, queued = 0, reasonCode = "", repairQueued = false, changedCount = 0, completed = 0 } = {}) {
  const result = {
    ok: Boolean(ok),
    changed: Boolean(changed),
    queued: Math.max(0, Number(queued) || 0),
    reasonCode: singleLine(reasonCode || ""),
    repairQueued: Boolean(repairQueued),
    changedCount: Math.max(0, Number(changedCount) || 0),
    completed: Math.max(0, Number(completed) || 0)
  };
  Object.defineProperty(result, "valueOf", { value: () => result.ok, enumerable: false });
  return result;
}

function localSemanticRoutingError(code, message, details = {}) {
  const error = new Error(`${String(code || "local-routing-error")}: ${String(message || "Local semantic routing failed.")}`);
  error.code = String(code || "local-routing-error");
  error.details = details && typeof details === "object" ? details : {};
  return error;
}

function localSemanticRoutingDescriptor(descriptor = {}) {
  if (!descriptor || typeof descriptor !== "object" || Array.isArray(descriptor)) throw localSemanticRoutingError("descriptor-malformed", "Encoder descriptor must be an object.");
  const id = descriptor.id;
  const version = descriptor.version;
  const dimension = Number(descriptor.dimension);
  const normalization = descriptor.normalization;
  const quantizationValue = descriptor.quantization;
  if (typeof id !== "string" || !id.trim() || version === undefined || version === null || (typeof version !== "string" && typeof version !== "number" && typeof version !== "boolean")) throw localSemanticRoutingError("descriptor-malformed", "Encoder id and version are required.");
  if (!Number.isInteger(dimension) || dimension < 1 || dimension > 16384) throw localSemanticRoutingError("descriptor-malformed", "Encoder dimension is invalid.", { dimension });
  if (typeof normalization !== "string" || !normalization.trim()) throw localSemanticRoutingError("descriptor-malformed", "Encoder normalization is required.");
  const normalizedNormalization = normalization.trim().toLowerCase();
  if (normalizedNormalization !== "l2" && normalizedNormalization !== "unit-l2" && normalizedNormalization !== "none") {
    throw localSemanticRoutingError("descriptor-unsupported", `Unsupported encoder normalization: ${normalization}.`);
  }
  if (quantizationValue === undefined || quantizationValue === null) throw localSemanticRoutingError("descriptor-malformed", "Encoder quantization is required.");
  let quantizationType = typeof quantizationValue === "string" ? quantizationValue : quantizationValue?.type || quantizationValue?.format;
  quantizationType = String(quantizationType || LOCAL_SEMANTIC_ROUTING_DEFAULT_QUANTIZATION).trim().toLowerCase();
  if (quantizationType !== LOCAL_SEMANTIC_ROUTING_DEFAULT_QUANTIZATION) throw localSemanticRoutingError("descriptor-unsupported", `Unsupported routing quantization: ${quantizationType}.`);
  const scale = Number(typeof quantizationValue === "object" ? quantizationValue?.scale : LOCAL_SEMANTIC_ROUTING_DEFAULT_QUANTIZATION_SCALE);
  if (!Number.isFinite(scale) || scale <= 0 || scale > LOCAL_SEMANTIC_ROUTING_DEFAULT_QUANTIZATION_SCALE) throw localSemanticRoutingError("descriptor-malformed", "Routing quantization scale is invalid.", { scale });
  return Object.freeze({ id, version, dimension, normalization: normalization.trim(), quantization: Object.freeze({ type: quantizationType, scale }) });
}

function localSemanticRoutingNow() {
  return typeof performance !== "undefined" && typeof performance.now === "function" ? performance.now() : Date.now();
}

function localSemanticRoutingVector(value, dimension, label, row, normalization) {
  if (!value || typeof value.length !== "number" || value.length !== dimension) throw localSemanticRoutingError("vector-malformed", `${label} vector dimension is invalid.`, { row, expected: dimension, actual: value?.length });
  const normalized = new Float64Array(dimension);
  let normSquared = 0;
  for (let index = 0; index < dimension; index += 1) {
    const number = Number(value[index]);
    if (!Number.isFinite(number)) throw localSemanticRoutingError("vector-malformed", `${label} vector contains a non-finite value.`, { row, index });
    normalized[index] = number;
    normSquared += number * number;
  }
  const normalizationMode = String(normalization || "").trim().toLowerCase();
  if (normalizationMode === "l2" || normalizationMode === "unit-l2") {
    const norm = Math.sqrt(normSquared);
    if (!Number.isFinite(norm) || norm <= Number.EPSILON) throw localSemanticRoutingError("vector-invalid", `${label} vector has zero magnitude.`, { row });
    for (let index = 0; index < dimension; index += 1) normalized[index] /= norm;
  }
  return normalized;
}

function localSemanticRoutingIdentity(value, label, row) {
  const identity = typeof value === "number" ? String(value) : typeof value === "string" ? value.trim() : "";
  if (!identity) throw localSemanticRoutingError("identity-malformed", `${label} identity is required.`, { row });
  return identity;
}

function localSemanticRoutingMetadata(value, seen = new WeakSet()) {
  if (value === null || value === undefined || typeof value === "string" || typeof value === "boolean") return value ?? null;
  if (typeof value === "number") {
    if (!Number.isFinite(value)) throw localSemanticRoutingError("metadata-malformed", "Temporal metadata contains a non-finite number.");
    return value;
  }
  if (typeof value !== "object") throw localSemanticRoutingError("metadata-malformed", "Temporal metadata contains an unsupported value.");
  if (seen.has(value)) throw localSemanticRoutingError("metadata-malformed", "Temporal metadata contains a cycle.");
  seen.add(value);
  if (Array.isArray(value)) {
    const copy = value.map((item) => localSemanticRoutingMetadata(item, seen));
    seen.delete(value);
    return Object.freeze(copy);
  }
  const copy = {};
  for (const key of Object.keys(value).sort()) copy[key] = localSemanticRoutingMetadata(value[key], seen);
  seen.delete(value);
  return Object.freeze(copy);
}

const LOCAL_SEMANTIC_ROUTING_TEXT_KEYS = new Set([
  "text", "content", "title", "description", "summary", "excerpt", "body", "prompt",
  "embedding", "vector", "routingVector", "routingEmbedding"
]);

function localSemanticRoutingCompactMetadata(value, seen = new WeakSet(), depth = 0) {
  if (value === null || value === undefined || typeof value === "string" || typeof value === "boolean") return value ?? null;
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value !== "object" || depth > 5) return null;
  if (seen.has(value)) return null;
  seen.add(value);
  if (Array.isArray(value)) {
    const copy = value.slice(0, LOCAL_SEMANTIC_ROUTING_MAX_METADATA_ARRAY_VALUES).map((item) => localSemanticRoutingCompactMetadata(item, seen, depth + 1));
    seen.delete(value);
    return Object.freeze(copy);
  }
  const copy = {};
  for (const key of Object.keys(value).sort().slice(0, LOCAL_SEMANTIC_ROUTING_MAX_METADATA_KEYS)) {
    const normalizedKey = String(key).replace(/[_-]/g, "").toLowerCase();
    if (LOCAL_SEMANTIC_ROUTING_TEXT_KEYS.has(String(key)) || /(?:text|content|title|description|summary|excerpt|body|prompt|embedding|vector)$/.test(normalizedKey)) continue;
    const child = localSemanticRoutingCompactMetadata(value[key], seen, depth + 1);
    if (child !== null && child !== undefined) copy[key] = child;
  }
  seen.delete(value);
  return Object.freeze(copy);
}

function localSemanticRoutingIdValues(values = [], fields = ["id", "ref"]) {
  const output = [];
  const visit = (value) => {
    if (output.length >= LOCAL_SEMANTIC_ROUTING_MAX_ID_VALUES) return;
    if (value === null || value === undefined || value === "") return;
    if (Array.isArray(value)) { for (const item of value) { visit(item); if (output.length >= LOCAL_SEMANTIC_ROUTING_MAX_ID_VALUES) break; } return; }
    if (typeof value === "object") { for (const field of fields) { visit(value[field]); if (output.length >= LOCAL_SEMANTIC_ROUTING_MAX_ID_VALUES) break; } return; }
    const normalized = String(value).trim();
    if (normalized && !output.includes(normalized)) output.push(normalized);
  };
  visit(values);
  return Object.freeze(output.slice(0, LOCAL_SEMANTIC_ROUTING_MAX_ID_VALUES));
}

function localSemanticRoutingTemporalMetadata(chunk = {}, provenance = {}, taskReference = {}) {
  const nested = chunk && typeof chunk === "object" ? chunk : {};
  const temporalObjects = [
    nested.temporalMetadata,
    nested.temporal,
    nested.source,
    nested.note,
    nested.snapshot,
    provenance.temporalMetadata,
    provenance.temporal,
    provenance.source,
    provenance.note,
    provenance.snapshot,
    taskReference.temporalMetadata,
    taskReference.temporal,
    taskReference.source,
    taskReference.note,
    taskReference.snapshot
  ].filter((value) => value && typeof value === "object" && !Array.isArray(value));
  const timestampSources = temporalObjects.concat([nested, provenance, taskReference]);
  const timestampFields = {
    createdAt: ["createdAt", "created_at", "dateCreated", "date_created", "created"],
    modifiedAt: ["modifiedAt", "modified_at", "updatedAt", "updated_at", "dateModified", "date_modified", "modified", "updated"],
    observedAt: ["observedAt", "observed_at", "cachedAt", "cached_at", "observed", "cached"],
    sourceTimestamp: ["sourceTimestamp", "source_timestamp", "sourceDate", "source_date"],
    noteTimestamp: ["noteTimestamp", "note_timestamp", "noteDate", "note_date"],
    snapshotTimestamp: ["snapshotTimestamp", "snapshot_timestamp", "snapshotDate", "snapshot_date", "snapshotRevision", "snapshot_revision"]
  };
  const hasValue = (value) => value !== undefined && value !== null && value !== "";
  const temporal = {};
  for (const source of timestampSources) {
    for (const [canonical, aliases] of Object.entries(timestampFields)) {
      if (hasValue(temporal[canonical])) continue;
      const alias = aliases.find((key) => hasValue(source[key]));
      if (alias) temporal[canonical] = source[alias];
    }
  }
  const explicitRelation = [
    nested.temporalRelation,
    nested.temporal_relation,
    nested.temporalMetadata?.temporalRelation,
    nested.temporalMetadata?.temporal_relation,
    nested.temporal?.temporalRelation,
    nested.temporal?.temporal_relation,
    provenance.temporalRelation,
    provenance.temporal_relation,
    provenance.temporalMetadata?.temporalRelation,
    provenance.temporalMetadata?.temporal_relation,
    provenance.temporal?.temporalRelation,
    provenance.temporal?.temporal_relation,
    taskReference.temporalRelation,
    taskReference.temporal_relation,
    taskReference.temporalMetadata?.temporalRelation,
    taskReference.temporalMetadata?.temporal_relation,
    taskReference.temporal?.temporalRelation,
    taskReference.temporal?.temporal_relation,
    nested.temporalMetadata?.relation,
    nested.temporal?.relation,
    provenance.temporalMetadata?.relation,
    provenance.temporal?.relation,
    taskReference.temporalMetadata?.relation,
    taskReference.temporal?.relation,
    ...temporalObjects.flatMap((source) => [source.temporalRelation, source.temporal_relation, source.relation])
  ].find(hasValue);
  const sourceMetadata = temporalObjects.reduce((merged, source) => Object.assign(merged, source), {});
  const compact = localSemanticRoutingCompactMetadata(Object.assign({}, sourceMetadata, temporal));
  if (!compact || typeof compact !== "object" || Array.isArray(compact)) return Object.freeze({ temporalRelation: String(explicitRelation || "unknown") });
  return Object.freeze(Object.assign({}, compact, {
    ...(explicitRelation !== undefined ? { temporalRelation: String(explicitRelation) } : { temporalRelation: "unknown" })
  }));
}

function localSemanticRoutingCanonicalMetadata(chunk = {}, evidenceId = "", sourceId = "") {
  const nested = chunk && typeof chunk === "object" ? chunk : {};
  const provenance = nested.provenance && typeof nested.provenance === "object" ? nested.provenance : {};
  const taskReference = nested.taskReference && typeof nested.taskReference === "object"
    ? nested.taskReference
    : (nested.task && typeof nested.task === "object" ? nested.task : {});
  const sourceIds = localSemanticRoutingIdValues([
    sourceId, nested.sourceId, nested.source_id, nested.source,
    provenance.sourceId, provenance.source_id,
    taskReference.sourceId, taskReference.source_id
  ], ["id", "ref", "sourceId", "source_id"]);
  const evidenceIds = localSemanticRoutingIdValues([
    evidenceId, nested.evidenceId, nested.evidence_id, nested.evidenceIds, nested.evidence_ids,
    provenance.evidenceId, provenance.evidence_id, provenance.evidenceIds,
    taskReference.evidenceId, taskReference.evidenceIds
  ], ["id", "ref", "evidenceId", "evidence_id"]);
  const scopeIds = localSemanticRoutingIdValues([
    nested.scopeId, nested.scope_id, nested.scopeIds, nested.scopeRefs, nested.scopes,
    provenance.scopeId, provenance.scope_id, provenance.scopeIds,
    taskReference.scopeId, taskReference.scope_id, taskReference.scopeIds
  ], ["id", "ref", "scopeId", "scope_id"]);
  const taskIds = localSemanticRoutingIdValues([
    nested.taskId, nested.task_id, nested.todoistId, nested.todoist_id,
    nested.taskIds, nested.taskRefs, provenance.taskId, provenance.task_id,
    taskReference.id, taskReference.taskId, taskReference.task_id, taskReference.todoistId,
    taskReference.todoist_id, taskReference.taskIds, taskReference.taskRefs
  ], ["id", "ref", "taskId", "task_id", "todoistId", "todoist_id"]);
  const factIds = localSemanticRoutingIdValues([
    nested.factId, nested.fact_id, nested.factIds, nested.fact_ids, nested.factRefs, nested.fact_refs,
    provenance.factId, provenance.fact_id, provenance.factIds, provenance.fact_refs,
    taskReference.factId, taskReference.factIds, taskReference.factRefs
  ], ["id", "ref", "factId", "fact_id"]);
  const childTaskIds = localSemanticRoutingIdValues([nested.childTaskIds, nested.child_task_ids, provenance.childTaskIds, taskReference.childTaskIds], ["id", "ref", "taskId", "task_id", "todoistId", "todoist_id"]);
  const childOids = localSemanticRoutingIdValues([nested.childOids, nested.child_oids, provenance.childOids, taskReference.childOids], ["id", "ref", "oid"]);
  const childEvidenceIds = localSemanticRoutingIdValues([nested.childEvidenceIds, nested.child_evidence_ids, provenance.childEvidenceIds, taskReference.childEvidenceIds], ["id", "ref", "evidenceId", "evidence_id"]);
  const temporal = localSemanticRoutingTemporalMetadata(nested, provenance, taskReference);
  const task = Object.freeze({
    ids: taskIds,
    taskId: String(nested.taskId || taskReference.taskId || taskReference.id || taskIds[0] || ""),
    oid: String(nested.oid || taskReference.oid || ""),
    parentId: String(nested.parentId || nested.parentTaskId || taskReference.parentId || taskReference.parentTaskId || provenance.parentId || ""),
    parentOid: String(nested.parentOid || taskReference.parentOid || provenance.parentOid || ""),
    rootId: String(nested.rootTaskId || nested.rootId || taskReference.rootTaskId || taskReference.rootId || provenance.rootTaskId || ""),
    rootOid: String(nested.rootOid || taskReference.rootOid || provenance.rootOid || ""),
    isSubtask: Boolean(nested.isSubtask ?? taskReference.isSubtask ?? Boolean(nested.parentId || nested.parentOid || taskReference.parentId || taskReference.parentOid)),
    childTaskIds,
    childOids,
    childEvidenceIds,
    treeDepth: Number(nested.treeDepth ?? taskReference.treeDepth ?? provenance.treeDepth ?? 0),
    treePath: localSemanticRoutingCompactMetadata(nested.treePath ?? taskReference.treePath ?? provenance.treePath ?? []),
    siblingOrder: Number.isFinite(Number(nested.siblingOrder ?? taskReference.siblingOrder ?? provenance.siblingOrder)) ? Number(nested.siblingOrder ?? taskReference.siblingOrder ?? provenance.siblingOrder) : null
  });
  const source = Object.freeze({
    id: String(sourceId || sourceIds[0] || ""),
    ids: sourceIds,
    kind: String(nested.sourceKind || nested.source_kind || provenance.sourceKind || provenance.source_kind || ""),
    path: String(nested.path || nested.sourcePath || nested.source_path || provenance.path || provenance.sourcePath || "")
  });
  const evidence = Object.freeze({
    id: String(evidenceId || evidenceIds[0] || ""),
    ids: evidenceIds,
    fingerprint: String(nested.evidenceContentFingerprint || nested.contentFingerprint || nested.content_fingerprint || ""),
    semanticUnitKind: String(nested.semanticUnitKind || nested.semantic_unit_kind || provenance.semanticUnitKind || provenance.semantic_unit_kind || ""),
    metadataOnly: Boolean(nested.metadataOnly ?? provenance.metadataOnly),
    evidenceEligibility: String(nested.evidenceEligibility || nested.evidence_eligibility || provenance.evidenceEligibility || provenance.evidence_eligibility || "evidence")
  });
  const provenanceMetadata = localSemanticRoutingCompactMetadata(Object.assign({}, provenance, {
    sourceKind: source.kind,
    sourceId: source.id,
    path: source.path,
    taskId: task.taskId,
    oid: task.oid,
    parentId: task.parentId,
    parentOid: task.parentOid,
    rootTaskId: task.rootId,
    rootOid: task.rootOid,
    childTaskIds,
    childOids,
    childEvidenceIds
  }));
  return Object.freeze({
    source,
    evidence,
    scope: Object.freeze({ ids: scopeIds }),
    task,
    factIds,
    temporal,
    provenance: provenanceMetadata
  });
}

function localSemanticRoutingVectorFromChunk(chunk = {}, row = 0) {
  const value = chunk.routingVector ?? chunk.routingEmbedding;
  if (value === undefined || value === null) {
    if (chunk.embedding !== undefined || chunk.vector !== undefined) {
      throw localSemanticRoutingError("vector-provider-incompatible", "Provider embedding/vector fields cannot populate local semantic routing; provide an explicit routingVector or routingEmbedding.", { row });
    }
    throw localSemanticRoutingError("vector-missing", "Semantic-index chunk has no explicit local routing vector.", { row });
  }
  return value;
}

// Provider-generated document embeddings are valid local semantic query
// handles only when their persisted provider/model/dimension/revision contract
// matches the request. They remain ordinary document vectors; never relabel
// them as routingVector or pass them through localSemanticRoutingVectorFromChunk.
function resolveIndexedSemanticQueryHandles(index = [], request = {}) {
  const startedAt = localSemanticRoutingNow();
  const mode = String(request.mode || "chat");
  const preferredIdentity = String(request.preferredIdentity || "").trim().toLowerCase();
  const requestedProvider = String(request.provider || "").trim().toLowerCase();
  const requestedModel = String(request.model || "");
  const requestedDimension = Number(request.dimension || 0);
  const requestedRevision = Number(request.indexRevision || 0);
  const allowReadyRevisionSkew = request.indexReady === true;
  const sourceContract = request.sourceContract && typeof request.sourceContract === "object" ? request.sourceContract : {};
  const toIds = (value) => (Array.isArray(value) ? value : [value])
    .flatMap((item) => item && typeof item === "object" ? [item.id, item.ref, item.evidenceId, item.evidence_id, item.sourceId, item.source_id, item.taskId, item.task_id, item.oid] : [item])
    .map((item) => String(item || "").trim())
    .filter(Boolean);
  const sourceIds = new Set(toIds([
    request.sourceId, ...(request.sourceIds || []), sourceContract.sourceId, sourceContract.source_id,
    sourceContract.path, sourceContract.sourcePath, sourceContract.source_path
  ]));
  const evidenceIds = new Set(toIds([
    request.evidenceId, ...(request.evidenceIds || []), sourceContract.primaryEvidenceId, sourceContract.primary_evidence_id,
    ...(sourceContract.primaryEvidenceIds || []), ...(sourceContract.evidenceIds || []), ...(sourceContract.evidence_ids || [])
  ]));
  const scopeIds = new Set(toIds([
    request.scopeId, ...(request.scopeIds || []), sourceContract.scopeId, sourceContract.scope_id,
    sourceContract.defaultScopeId, sourceContract.default_scope_id, ...(sourceContract.scopeIds || [])
  ]));
  const task = request.task && typeof request.task === "object" ? request.task : {};
  const taskIds = new Set(toIds([
    request.taskId, ...(request.taskIds || []), task.id, task.taskId, task.task_id, task.todoistId, task.todoist_id,
    task.oid, ...(task.taskIds || []), ...(task.task_ids || []), ...(task.evidenceTaskIds || [])
  ]));
  const factIds = new Set(toIds([
    ...(request.factIds || []), ...(task.fact_refs || []), ...(task.factRefs || []), ...(task.mandatoryTaskFactIds || []),
    ...(task.requiredFactIds || []), ...(sourceContract.factIds || []), ...(sourceContract.fact_ids || []),
    ...(sourceContract.fact_refs || []), ...(sourceContract.primaryContextFactIds || [])
  ]));
  const requestedIdentityCount = sourceIds.size + evidenceIds.size + scopeIds.size + taskIds.size + factIds.size;
  const candidates = [];
  const rejected = [];
  const normalizeIdentity = (value) => String(value || "").trim();
  const knownMetadata = (...values) => values.find((value) => value !== undefined && value !== null && String(value).trim() && String(value).trim().toLowerCase() !== "unknown") || "";
  const metadata = (chunk) => Object.assign({}, chunk?.indexMetadata || {}, {
    provider: knownMetadata(chunk?.embeddingProvider, chunk?.indexMetadata?.provider, request.indexProvider, requestedProvider),
    model: knownMetadata(chunk?.embeddingModel, chunk?.indexMetadata?.model, request.indexModel, requestedModel),
    dimension: chunk?.embeddingDimension || chunk?.indexMetadata?.dimension || (Array.isArray(chunk?.embedding) ? chunk.embedding.length : 0),
    contentVersion: chunk?.embeddingContentVersion || chunk?.indexMetadata?.contentVersion || SEMANTIC_EMBEDDING_CONTENT_VERSION,
    indexRevision: chunk?.indexRevision || chunk?.indexMetadata?.indexRevision || requestedRevision
  });
  const matches = (chunk) => {
    const taskReference = chunk?.taskReference || chunk?.task || {};
    const chunkSourceIds = new Set(toIds([chunk?.sourceId, chunk?.source, chunk?.path, chunk?.provenance?.sourceId, taskReference.sourceId, taskReference.source_id]));
    const chunkEvidenceIds = new Set(toIds([chunk?.evidenceId, chunk?.evidence_id, chunk?.provenance?.evidenceId, ...(chunk?.evidenceIds || []), ...(taskReference.evidenceIds || [])]));
    const chunkScopeIds = new Set(toIds([chunk?.scopeId, chunk?.scope_id, ...(chunk?.scopeIds || []), ...(chunk?.scopeRefs || []), ...(taskReference.scopeIds || []), taskReference.scopeId]));
    const chunkTaskIds = new Set(toIds([chunk?.taskId, chunk?.task_id, chunk?.todoistId, chunk?.todoist_id, chunk?.oid, taskReference.id, taskReference.taskId, taskReference.task_id, taskReference.todoistId, taskReference.todoist_id, taskReference.oid]));
    const chunkFactIds = new Set(toIds([...(chunk?.factIds || []), ...(chunk?.fact_ids || []), ...(chunk?.factRefs || []), ...(chunk?.fact_refs || []), ...(taskReference.factIds || []), ...(taskReference.fact_refs || [])]));
    const exact = (left, right) => Array.from(left).some((value) => right.has(value));
    const evidenceMatch = exact(evidenceIds, chunkEvidenceIds);
    const sourceMatch = exact(sourceIds, chunkSourceIds);
    const taskMatch = exact(taskIds, chunkTaskIds);
    const factMatch = exact(factIds, chunkFactIds);
    const scopeMatch = exact(scopeIds, chunkScopeIds);
    const matched = evidenceMatch || sourceMatch || taskMatch || factMatch || scopeMatch;
    const taskMode = mode === "schedule" || mode === "scheduler" || mode.includes("dedup") || mode.includes("duplicate");
    const preferredRank = preferredIdentity === "task" && taskMatch ? 10
      : preferredIdentity === "evidence" && evidenceMatch ? 10
        : preferredIdentity === "source" && sourceMatch ? 10
          : 0;
    const rank = preferredRank || (taskMode && taskMatch ? 9 : evidenceMatch ? 8 : factMatch ? 7 : sourceMatch ? 6 : taskMatch ? 5 : scopeMatch ? 1 : 0);
    return { matched, rank, evidenceMatch, sourceMatch, taskMatch, factMatch, scopeMatch };
  };
  const compatibleEntry = (chunk, row, match) => {
    const values = chunk?.embedding;
    const meta = metadata(chunk);
    const provider = String(meta.provider || "").trim().toLowerCase();
    const model = String(meta.model || "");
    const dimension = Number(meta.dimension || 0);
    const revision = Number(meta.indexRevision || 0);
    const compatible = Array.isArray(values) && values.length > 0
      && (!requestedProvider || !provider || provider === requestedProvider)
      && (!requestedModel || !model || modelIdentity(model) === modelIdentity(requestedModel))
      && (!requestedDimension || dimension === requestedDimension)
      && (!requestedRevision || !revision || revision === requestedRevision || allowReadyRevisionSkew)
      && Number(meta.contentVersion || SEMANTIC_EMBEDDING_CONTENT_VERSION) === SEMANTIC_EMBEDDING_CONTENT_VERSION;
    return compatible ? { chunk, match, row, meta } : null;
  };
  for (let row = 0; row < (index || []).length; row += 1) {
    const chunk = index[row];
    if (!chunk || typeof chunk !== "object") continue;
    const match = matches(chunk);
    if (!match.matched) continue;
    const entry = compatibleEntry(chunk, row, match);
    if (!entry) {
      const meta = metadata(chunk);
      rejected.push({ evidenceId: String(chunk.evidenceId || chunk.id || ""), sourceId: String(chunk.sourceId || ""), reasonCode: "indexed-handle-incompatible", provider: String(meta.provider || "").trim().toLowerCase(), model: String(meta.model || ""), dimension: Number(meta.dimension || 0), revision: Number(meta.indexRevision || 0) });
      continue;
    }
    candidates.push(entry);
  }
  const highestIdentityRank = candidates.reduce((highest, candidate) => Math.max(highest, candidate.match.rank), 0);
  const maxHandles = Math.max(1, Math.min(16, Number(request.maxHandles || 8)));
  const highestIdentityCandidates = candidates.filter((candidate) => candidate.match.rank === highestIdentityRank);
  const sourceIdentity = (candidate) => String(
    candidate?.chunk?.sourceId
      || candidate?.chunk?.provenance?.sourceId
      || candidate?.chunk?.path
      || candidate?.chunk?.provenance?.path
      || candidate?.chunk?.evidenceId
      || candidate?.chunk?.id
      || ""
  ).trim();
  const candidateKey = (candidate) => `${String(candidate?.chunk?.evidenceId || candidate?.chunk?.id || "")}:${sourceIdentity(candidate)}`;
  const sortedByEvidence = (values) => values.slice().sort((left, right) =>
    sourceIdentity(left).localeCompare(sourceIdentity(right))
    || String(left.chunk.evidenceId || left.chunk.id || "").localeCompare(String(right.chunk.evidenceId || right.chunk.id || "")));
  const selectedCandidates = [];
  const selectedKeys = new Set();
  // Query handles are protected identity seeds only. Routed evidence rows
  // must never become independent document-vector query handles.
  for (const candidate of sortedByEvidence(highestIdentityCandidates)) {
    if (selectedCandidates.length >= maxHandles) break;
    const key = candidateKey(candidate);
    if (selectedKeys.has(key)) continue;
    selectedKeys.add(key);
    selectedCandidates.push(candidate);
  }
  const seenVectors = new Set();
  const handles = selectedCandidates.filter(({ chunk, meta }) => {
    const key = `${chunk.evidenceId || chunk.id || ""}|${chunk.sourceId || ""}|${meta.dimension}|${meta.model}`;
    if (seenVectors.has(key)) return false;
    seenVectors.add(key);
    return true;
  }).map(({ chunk, meta }) => {
    const provider = String(meta.provider || requestedProvider || "");
    const model = String(meta.model || requestedModel || "");
    const dimension = Number(meta.dimension || requestedDimension || chunk.embedding.length);
    const activeRevision = requestedRevision || Number(meta.indexRevision || 0);
    const sourceEvidenceIds = uniqueValues([chunk.evidenceId, ...(chunk.evidenceIds || []), ...(chunk.provenance?.evidenceIds || [])].map(String).filter(Boolean));
    const sourceIds = uniqueValues([chunk.sourceId, chunk.provenance?.sourceId, chunk.path].map(String).filter(Boolean));
    return Object.freeze({
      source: "indexed",
      encoderId: `${provider}:${model}`,
      encoderVersion: Number(meta.contentVersion || SEMANTIC_EMBEDDING_CONTENT_VERSION),
      // Reuse the validated indexed document vector; copying every full
      // embedding per request would violate warm retrieval/resource bounds.
      vector: chunk.embedding,
      provider,
      model,
      dimension,
      indexRevision: activeRevision,
      sourceEvidenceIds: Object.freeze(sourceEvidenceIds),
      sourceIds: Object.freeze(sourceIds),
      scopeIds: Object.freeze(uniqueValues([chunk.scopeId, ...(chunk.scopeIds || [])].map(String).filter(Boolean))),
      taskIds: Object.freeze(uniqueValues([chunk.taskId, chunk.todoistId, chunk.oid].map(String).filter(Boolean))),
      cacheKey: `indexed:${provider}:${model}:${dimension}:${activeRevision}:${chunk.evidenceId || chunk.id || shortHash(JSON.stringify(chunk.embedding))}`
    });
  });
  const degradedReason = mode === "chat" ? "" : handles.length ? "" : (request.indexReady === true || index?.length ? "query-vector-unavailable" : "local-warmup-required");
  return Object.freeze({
    handles: Object.freeze(handles),
    degradedReason,
    telemetry: Object.freeze({
      source: mode === "chat" ? "chat-provider" : "indexed",
      handleSource: mode === "chat" ? "chat-provider" : "indexed",
      mode,
      requestedIdentityCount,
      selectedIdentityRank: highestIdentityRank,
      selectedIdentityRankCount: selectedCandidates.filter((candidate) => candidate.match.rank === highestIdentityRank).length,
      selectedSourceCount: new Set(selectedCandidates.map(sourceIdentity).filter(Boolean)).size,
      indexedHandleCount: handles.length,
      incompatibleHandleCount: rejected.length,
      rejected: Object.freeze(rejected.slice(0, SEMANTIC_RETRIEVAL_MAX_REJECTED)),
      externalQueryEmbeddingCalls: 0,
      runtimeExternalCalls: 0,
      resolveElapsedMs: Math.max(0, localSemanticRoutingNow() - startedAt)
    })
  });
}

