  async routeProductionSemanticCandidates(queryHandles = [], usableIndex = [], options = {}) {
    const result = await this.routeProductionSemanticCandidateBatches([{
      groupId: options.groupId || "default",
      handles: queryHandles,
      topK: Math.max(Number(options.limit || 1) * 6, Number(options.topK || 40)),
      requiredEvidenceIds: options.requiredEvidenceIds || []
    }], usableIndex, options);
    const group = result.groups[0] || { candidates: [], degradedReason: result.degradedReason || "" };
    return { candidates: group.candidates || [], telemetry: result.telemetry, degradedReason: group.degradedReason || result.degradedReason || "", routingState: result.routingState };
  }

  async retrieveAdaptiveSemanticContext(query, mode = "chat", baseLimit = 8, prompt = "", options = {}) {
    // Accept the compact `(query, mode, options)` form as well as the
    // expanded `(query, mode, limit, prompt, options)` form. The former must
    // not silently discard its source/query identity.
    if (baseLimit && typeof baseLimit === "object" && !Array.isArray(baseLimit)) {
      options = Object.assign({}, baseLimit, options && typeof options === "object" ? options : {});
      baseLimit = options.limit || this.settings.maxChatContextChunks || 8;
      prompt = options.prompt || (ADAPTIVE_CONTEXT_MODE_BUDGETS[mode] ? query : String(mode || query));
      mode = options.mode || (ADAPTIVE_CONTEXT_MODE_BUDGETS[mode] ? mode : "chat");
    }
    const retrievalOptions = options && typeof options === "object" ? options : {};
    const plan = contextQueryPlan(prompt || query, mode, retrievalOptions.queryPlan || {});
    const suppliedContract = retrievalOptions.sourceContract && typeof retrievalOptions.sourceContract === "object"
      ? retrievalOptions.sourceContract
      : null;
    if (suppliedContract) {
      const sourcePath = vaultRelativePath(suppliedContract.path || suppliedContract.sourcePath || suppliedContract.source_path || "");
      const sourceType = String(suppliedContract.sourceType || suppliedContract.source_type || "note").toLowerCase();
      const suppliedSourceId = String(suppliedContract.sourceId || suppliedContract.source_id || suppliedContract.id || "").trim();
      const canonicalSourceId = sourceType === "note" && sourcePath
        ? `note://${sourcePath}`
        : suppliedSourceId;
      const normalizedContract = Object.assign({}, suppliedContract);
      if (canonicalSourceId && !normalizedContract.sourceId) normalizedContract.sourceId = canonicalSourceId;
      if (canonicalSourceId && !normalizedContract.source_id) normalizedContract.source_id = canonicalSourceId;
      plan.sourceContractId = normalizedContract.id || normalizedContract.sourceId || "";
      plan.sourceContract = normalizedContract;
      plan.sourceId = canonicalSourceId || normalizedContract.sourceId || normalizedContract.source_id || "";
      plan.sourcePath = sourcePath;
      plan.primaryEvidenceId = normalizedContract.primaryEvidenceId || normalizedContract.primary_evidence_id || "";
    }
    return this.retrieveSemanticContext(query, adaptiveSemanticRetrievalLimit(this.settings, mode, baseLimit, prompt || query, { queryPlan: plan }), plan);
  }

