function settingDescription(name, key, fallback = "") {
  return fallback || SETTING_DESCRIPTIONS[key] || SETTING_DESCRIPTIONS[name] || "";
}

function sanitizeLogData(value) {
  if (value == null) return value;
  if (typeof value === "string") return redactSecrets(value);
  if (typeof value === "number" || typeof value === "boolean") return value;
  if (Array.isArray(value)) return value.map(sanitizeLogData);
  if (typeof value === "object") {
    const out = {};
    for (const [key, item] of Object.entries(value)) {
      if (/key|token|authorization|secret|password/i.test(key)) out[key] = "[redacted]";
      else out[key] = sanitizeLogData(item);
    }
    return out;
  }
  return String(value);
}

function redactSecrets(value) {
  return String(value || "")
    .replace(/AIza[0-9A-Za-z_-]{20,}/g, "[redacted-google-key]")
    .replace(/sk-(proj-)?[0-9A-Za-z_-]{20,}/g, "[redacted-openai-key]")
    .replace(/Bearer\s+[0-9A-Za-z._-]+/gi, "Bearer [redacted]");
}

function randomSetupToken() {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
  const bytes = new Uint8Array(32);
  if (globalThis.crypto?.getRandomValues) globalThis.crypto.getRandomValues(bytes);
  else for (let i = 0; i < bytes.length; i += 1) bytes[i] = Math.floor(Math.random() * 256);
  return Array.from(bytes, (byte) => alphabet[byte % alphabet.length]).join("");
}

function isHttpsUrl(value) {
  try {
    const url = new URL(String(value || ""));
    return url.protocol === "https:";
  } catch {
    return false;
  }
}

function normalizeHttpsUrl(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/^https?:\/\//i.test(text)) return text.replace(/^http:\/\//i, "https://");
  return `https://${text}`;
}

function textSetting(containerEl, name, desc, plugin, key) {
  new Setting(containerEl).setName(name).setDesc(settingDescription(name, key, desc)).addText((text) => text.setValue(String(plugin.settings[key] || "")).onChange(async (value) => {
    plugin.settings[key] = key === "workerUrl" ? normalizeHttpsUrl(value) : value;
    await plugin.saveSettings();
  }));
}

function stsMpDefaultProviderSettings(settings = {}, value = "", registry = typeof STS_MULTI_PROVIDER !== "undefined" ? STS_MULTI_PROVIDER : null) {
  if (!registry) return null;
  const current = settings && typeof settings === "object" ? settings : {};
  const inferred = typeof registry.providerForModel === "function"
    ? registry.providerForModel(current.chatModel, current)
    : aiProviderForModel(current.chatModel);
  const fallback = registry.normalizeProvider(current.aiModelProvider, inferred || "openai");
  const provider = registry.normalizeProvider(value, fallback);
  const migratedCurrent = typeof registry.migrateOperationModelSettings === "function"
    ? registry.migrateOperationModelSettings(current).settings
    : current;
  const catalog = registry.catalogRows(migratedCurrent);
  const applied = typeof registry.applyProviderToOperationRole === "function"
    ? registry.applyProviderToOperationRole(migratedCurrent, provider, "primary", catalog)
    : typeof registry.seedDefaultProvider === "function"
      ? registry.seedDefaultProvider(migratedCurrent, provider, catalog)
      : migratedCurrent;
  const result = Object.assign({}, applied || migratedCurrent || current, { aiModelProvider: provider });
  if (applied?.providerRoleRouting) Object.defineProperty(result, "providerRoleRouting", { value: applied.providerRoleRouting, enumerable: false, configurable: true, writable: false });
  return result;
}

function stsMpFallbackProviderSettings(settings = {}, value = "", registry = typeof STS_MULTI_PROVIDER !== "undefined" ? STS_MULTI_PROVIDER : null) {
  if (!registry) return null;
  const current = settings && typeof settings === "object" ? settings : {};
  const operationProviders = registry.OPERATION_KEYS
    .map((operation) => registry.operationModelReference(current, operation)?.fallback?.provider)
    .filter(Boolean);
  const inferred = operationProviders.length && operationProviders.every((provider) => provider === operationProviders[0])
    ? operationProviders[0]
    : current.fallbackAiModelProvider || registry.providerForModel(current.chatFallbackModel, current);
  const provider = registry.normalizeProvider(value, inferred || "openai");
  const migratedCurrent = typeof registry.migrateOperationModelSettings === "function"
    ? registry.migrateOperationModelSettings(current).settings
    : current;
  const catalog = registry.catalogRows(migratedCurrent);
  const applied = typeof registry.applyProviderToOperationRole === "function"
    ? registry.applyProviderToOperationRole(migratedCurrent, provider, "fallback", catalog)
    : migratedCurrent;
  const result = Object.assign({}, applied || migratedCurrent || current, { fallbackAiModelProvider: provider });
  if (applied?.providerRoleRouting) Object.defineProperty(result, "providerRoleRouting", { value: applied.providerRoleRouting, enumerable: false, configurable: true, writable: false });
  return result;
}

function aiProviderSetting(containerEl, plugin, refreshDisplay) {
  const current = STS_MULTI_PROVIDER.normalizeProvider(
    plugin.settings.aiModelProvider,
    STS_MULTI_PROVIDER.providerForModel(plugin.settings.chatModel, plugin.settings)
  );
  const setting = new Setting(containerEl)
    .setName("Primary AI Provider")
    .setDesc(settingDescription("Primary AI Provider", "aiModelProvider", "Changing this updates the primary provider and model reference for every generation operation. Embedding selection remains independent."));
  setting.settingEl?.addClass?.("semantic-todoist-provider-setting");
  setting.addDropdown((dropdown) => {
      const providers = STS_MULTI_PROVIDER.PROVIDER_DISPLAY_ORDER;
      for (const provider of providers) {
        const normalized = STS_MULTI_PROVIDER.normalizeProvider(provider);
        const label = STS_MULTI_PROVIDER.providerDisplayName(normalized);
        dropdown.addOption(normalized, label);
      }
      dropdown.setValue(current).onChange(async (value) => {
        plugin.settings = stsMpDefaultProviderSettings(plugin.settings, value);
        await plugin.saveSettings();
        const omitted = plugin.settings.providerRoleRouting?.omittedCollisions?.length || 0;
        if (omitted) new Notice(`Primary routing omitted ${omitted} incompatible fallback reference${omitted === 1 ? "" : "s"}.`);
        if (refreshDisplay) refreshDisplay();
      });
    });
}

function fallbackAiProviderSetting(containerEl, plugin, refreshDisplay) {
  const current = STS_MULTI_PROVIDER.normalizeProvider(
    plugin.settings.fallbackAiModelProvider,
    STS_MULTI_PROVIDER.providerForModel(plugin.settings.chatFallbackModel, plugin.settings)
  );
  const setting = new Setting(containerEl)
    .setName("Fallback AI Provider")
    .setDesc(settingDescription("Fallback AI Provider", "fallbackAiModelProvider", "Changing this updates the fallback provider and model reference for every generation operation. The saved fallback map is preserved while global fallback is off."));
  setting.settingEl?.addClass?.("semantic-todoist-provider-setting");
  setting.addDropdown((dropdown) => {
    for (const provider of STS_MULTI_PROVIDER.PROVIDER_DISPLAY_ORDER) {
      const normalized = STS_MULTI_PROVIDER.normalizeProvider(provider);
      dropdown.addOption(normalized, STS_MULTI_PROVIDER.providerDisplayName(normalized));
    }
    dropdown.setValue(current).onChange(async (value) => {
      try {
        plugin.settings = stsMpFallbackProviderSettings(plugin.settings, value);
        await plugin.saveSettings();
        const omitted = plugin.settings.providerRoleRouting?.omittedCollisions?.length || 0;
        if (omitted) new Notice(`Fallback routing omitted ${omitted} primary/fallback collision${omitted === 1 ? "" : "s"}.`);
        if (refreshDisplay) refreshDisplay();
      } catch (error) {
        new Notice(error.message || String(error));
      }
    });
  });
}

function reasoningEffortSetting(containerEl, name, desc, plugin, key, model) {
  const current = normalizeReasoningEffort(plugin.settings[key], DEFAULT_SETTINGS[key]);
  const options = reasoningEffortOptionsForModel(model, current);
  const modelName = modelDisplayName(model, plugin.settings);
  const provider = typeof STS_MULTI_PROVIDER !== "undefined"
    ? STS_MULTI_PROVIDER.providerForModel(model, plugin.settings)
    : aiProviderForModel(model, plugin.settings);
  const providerNote = provider === "openai"
    ? "OpenAI reasoning models use the Responses API reasoning.effort field."
    : provider === "gemini" && isGemini3ReasoningModel(model)
      ? "Gemini 3 models use the provider's thinkingLevel field."
      : "This model has no compatible level control here, so Provider default is used.";
  new Setting(containerEl)
    .setName(name)
    .setDesc(`${desc} Active model: ${modelName}. ${providerNote}`)
    .addDropdown((dropdown) => {
      for (const option of options) dropdown.addOption(option.value, option.label);
      dropdown.setValue(current).onChange(async (value) => {
        plugin.settings[key] = normalizeReasoningEffort(value);
        await plugin.saveSettings();
      });
    });
}

function taskGenerationPromptTemplateSetting(containerEl, plugin) {
  const current = plugin.settings.taskGenerationPromptTemplate || DEFAULT_SETTINGS.taskGenerationPromptTemplate;
  new Setting(containerEl)
    .setName("Task generation prompt")
    .setDesc("Default task-generation prompt used by the Create Todoist tasks command. Prompt templates with createTasks enabled use their own prompt text directly.")
    .addDropdown((dropdown) => {
      dropdown.addOption(current, current);
      dropdown.setValue(current);
      dropdown.onChange(async (value) => {
        plugin.settings.taskGenerationPromptTemplate = value;
        await plugin.saveSettings();
      });
      plugin.getPromptTemplates().then((templates) => {
        const candidates = templates.filter((template) => isTaskGenerationTemplate(template));
        if (dropdown.selectEl) dropdown.selectEl.empty();
        const values = new Set();
        for (const template of candidates) {
          const value = template.source || template.name;
          if (!value || values.has(value)) continue;
          values.add(value);
          dropdown.addOption(value, template.name || value);
        }
        if (!values.has(current)) dropdown.addOption(current, current);
        dropdown.setValue(values.has(current) ? current : (candidates[0]?.source || candidates[0]?.name || current));
      }).catch((error) => {
        console.error("Could not load task generation templates", error);
      });
    });
}

function taskGenerationPromptProfileSettings(containerEl, plugin) {
  new Setting(containerEl)
    .setName("Task-generation prompt profile mode")
    .setDesc(settingDescription("Task-generation prompt profile mode", "taskGenerationPromptProfileMode", "Auto follows the exact configured primary model when it is GPT 5.6 Luna or GPT 5.6 Terra; Manual uses the saved profile below."))
    .addDropdown((dropdown) => {
      dropdown.addOption("auto", "Auto");
      dropdown.addOption("manual", "Manual");
      dropdown.setValue(normalizeTaskGenerationPromptProfileMode(plugin.settings.taskGenerationPromptProfileMode)).onChange(async (value) => {
        plugin.settings.taskGenerationPromptProfileMode = normalizeTaskGenerationPromptProfileMode(value);
        await plugin.saveSettings();
      });
    });
  new Setting(containerEl)
    .setName("Task-generation prompt profile")
    .setDesc(settingDescription("Task-generation prompt profile", "taskGenerationPromptProfile", "Choose the bounded task and description guidance used when prompt profile mode is Manual."))
    .addDropdown((dropdown) => {
      for (const profile of TASK_GENERATION_PROMPT_PROFILES) dropdown.addOption(profile, TASK_GENERATION_PROMPT_PROFILE_NAMES[profile]);
      dropdown.setValue(normalizeTaskGenerationPromptProfile(plugin.settings.taskGenerationPromptProfile)).onChange(async (value) => {
        plugin.settings.taskGenerationPromptProfile = normalizeTaskGenerationPromptProfile(value);
        await plugin.saveSettings();
      });
    });
}

function todoistProjectSetting(containerEl, plugin, refreshDisplay) {
  const projects = plugin.settings.availableTodoistProjects || [];
  const currentId = plugin.settings.todoistTaskProjectId || plugin.settings.todoistInboxProjectId || "";
  const currentName = plugin.settings.todoistTaskProjectName || "Inbox";
  const desc = projects.length
    ? `New email and note tasks are created in this Todoist project. Projects loaded: ${projects.length}. Last refreshed: ${plugin.settings.todoistProjectsFetchedAt || "unknown"}.`
    : "Defaults to Todoist Inbox. Refresh after adding your Todoist token to choose another project.";
  const setting = new Setting(containerEl).setName("Todoist task project").setDesc(desc)
    .addDropdown((dropdown) => {
      if (currentId && !projects.some((project) => project.id === currentId)) dropdown.addOption(currentId, currentName);
      if (!projects.length && !currentId) dropdown.addOption("", "Inbox");
      for (const project of projects) dropdown.addOption(project.id, project.isInbox ? `${project.name} (Inbox)` : project.name);
      dropdown.setValue(currentId || "");
      dropdown.onChange(async (value) => {
        const selected = projects.find((project) => project.id === value);
        plugin.settings.todoistTaskProjectId = value;
        plugin.settings.todoistTaskProjectName = selected?.name || currentName || "Inbox";
        await plugin.saveSettings();
      });
    })
    .addButton((button) => button.setButtonText("Refresh").onClick(async () => {
      try {
        await plugin.refreshTodoistProjects(true);
        if (refreshDisplay) refreshDisplay();
      } catch (error) {
        new Notice(`Could not load Todoist projects: ${error.message || error}`);
      }
    }));
  setting.settingEl.addClass("semantic-todoist-project-setting");
}

function secretSetting(containerEl, name, plugin, key) {
  new Setting(containerEl).setName(name).setDesc(settingDescription(name, key)).addText((text) => {
    text.inputEl.type = "password";
    text.setValue(String(plugin.settings[key] || "")).onChange(async (value) => {
      plugin.settings[key] = value.trim();
      await plugin.saveSettings();
    });
  });
}

function numberSetting(containerEl, name, plugin, key) {
  new Setting(containerEl).setName(name).setDesc(settingDescription(name, key)).addText((text) => {
    text.inputEl.type = "number";
    text.setValue(String(plugin.settings[key] ?? DEFAULT_SETTINGS[key])).onChange(async (value) => {
      const minimum = key === "emailPollIntervalSeconds" ? MIN_EMAIL_AUTO_POLL_INTERVAL_SECONDS : ["scheduleTodayLunchMinutes", "scheduleTodayAddWindowMinutes"].includes(key) ? 0 : 1;
      const maximum = key === "runtimeWorkerCount" ? 8 : key === "aiModelConcurrency" ? 16 : Number.POSITIVE_INFINITY;
      const parsed = parseInt(value, 10);
      plugin.settings[key] = Math.min(maximum, Math.max(minimum, Number.isFinite(parsed) ? parsed : DEFAULT_SETTINGS[key]));
      await plugin.saveSettings();
    });
  });
}

function unknownModelContextWindowSetting(containerEl, plugin) {
  const setting = new Setting(containerEl)
    .setName("Unknown model context window")
    .setDesc("Provider-neutral positive integer estimate used only when exact model metadata, an exact model override, and any documented provider profile are unavailable; exact metadata and overrides take precedence. Editing allows an empty/intermediate value and saves the bounded value on blur.");
  setting.settingEl?.addClass?.("semantic-todoist-unknown-context-setting");
  setting.addText((text) => {
    text.inputEl.type = "number";
    text.inputEl.min = String(UNKNOWN_MODEL_CONTEXT_WINDOW_MIN_TOKENS);
    text.inputEl.max = String(UNKNOWN_MODEL_CONTEXT_WINDOW_MAX_TOKENS);
    text.inputEl.step = "1";
    text.inputEl.setAttribute("aria-label", "Unknown model context window tokens");
    text.inputEl.addClass?.("semantic-todoist-unknown-model-context-input");
    text.setValue(String(unknownModelContextWindowTokens(plugin.settings || DEFAULT_SETTINGS)));
    let pending = text.inputEl.value;
    text.inputEl.addEventListener("input", () => { pending = text.inputEl.value; });
    text.inputEl.addEventListener("blur", async () => {
      const next = normalizeUnknownModelContextWindowTokens(pending);
      plugin.settings.unknownModelContextWindowTokens = next;
      text.setValue(String(next));
      await plugin.saveSettings();
    });
  });
  return setting;
}

function timeSetting(containerEl, name, desc, plugin, key) {
  const setting = new Setting(containerEl).setName(name).setDesc(settingDescription(name, key, desc));
  const input = setting.controlEl.createEl("input", { type: "time" });
  input.value = String(plugin.settings[key] || DEFAULT_SETTINGS[key] || "");
  input.onchange = async () => {
    plugin.settings[key] = input.value || DEFAULT_SETTINGS[key];
    await plugin.saveSettings();
  };
}

function scheduleWeightSetting(containerEl, name, plugin, key) {
  const options = ["less", "moderate", "more"];
  const labels = { less: "Less", moderate: "Moderate", more: "More" };
  const current = options.includes(plugin.settings[key]) ? plugin.settings[key] : "moderate";
  const setting = new Setting(containerEl).setName(name).setDesc(settingDescription(name, key));
  setting.settingEl.addClass("semantic-todoist-weight-setting");
  const wrapper = setting.controlEl.createDiv({ cls: "semantic-todoist-weight-control" });
  const range = wrapper.createEl("input", { type: "range", attr: { min: "0", max: "2", step: "1", "aria-label": name } });
  const label = wrapper.createSpan({ cls: "semantic-todoist-weight-label", text: labels[current] });
  range.value = String(Math.max(0, options.indexOf(current)));
  range.oninput = () => {
    label.setText(labels[options[Number(range.value)] || "moderate"]);
  };
  range.onchange = async () => {
    plugin.settings[key] = options[Number(range.value)] || "moderate";
    await plugin.saveSettings();
  };
}

