function activitySetting(containerEl, name, desc) {
  new Setting(containerEl).setName(name).setDesc(desc || "");
}

function activityLogDataText(value, key = "") {
  if (value == null) return "";
  if (typeof value === "string") {
    return /(?:^|_)(?:at|timestamp|date|time)$/i.test(String(key || "")) ? (formatDeviceDateTime(value) || value) : value;
  }
  if (Array.isArray(value)) return value.map((item) => activityLogDataText(item, key)).join(", ");
  if (typeof value === "object") {
    const normalized = {};
    for (const [childKey, childValue] of Object.entries(value)) normalized[childKey] = activityLogDataText(childValue, childKey);
    return JSON.stringify(normalized);
  }
  return String(value);
}

function setupStatusSetting(containerEl, name, desc, buttons = []) {
  const setting = new Setting(containerEl).setName(name).setDesc(desc || "");
  setting.settingEl.addClass("semantic-todoist-setup-step");
  for (const [label, onClick] of buttons) {
    setting.addButton((button) => button.setButtonText(label).onClick(onClick));
  }
}

function parsePromptTemplateFile(file, text) {
  const parsed = parseSimpleFrontmatter(text);
    return {
      name: parsed.meta.name || file.basename,
      prompt: parsed.body.trim(),
      source: file.path,
      action: normalizePromptTemplateAction(parsed.meta.action ?? parsed.meta.actionType ?? parsed.meta.action_type ?? parsed.meta.templateAction ?? parsed.meta.template_action),
      createTasks: parseTemplateBoolean(parsed.meta.createTasks ?? parsed.meta.create_tasks ?? parsed.meta.makeTasks ?? parsed.meta.make_tasks, false),
      insertResponse: parseTemplateBoolean(parsed.meta.insertResponse ?? parsed.meta.insert_response, true),
      syncAfterInsert: parseTemplateBoolean(parsed.meta.syncTasks ?? parsed.meta.sync_tasks ?? parsed.meta.syncAfterInsert ?? parsed.meta.sync_after_insert, false),
      taskHeading: parsed.meta.taskHeading || parsed.meta.task_heading || parsed.meta.heading || "",
      taskGenerationTemplate: parseOptionalTemplateBoolean(parsed.meta.taskGenerationTemplate ?? parsed.meta.task_generation_template ?? parsed.meta.taskTemplate ?? parsed.meta.task_template ?? parsed.meta.taskOnly ?? parsed.meta.task_only)
    };
}

function parseSimpleFrontmatter(text) {
  const value = String(text || "");
  if (!value.startsWith("---")) return { meta: {}, body: value };
  const end = value.indexOf("\n---", 3);
  if (end < 0) return { meta: {}, body: value };
  const raw = value.slice(3, end).trim();
  const body = value.slice(end + 4).replace(/^\s*\n/, "");
  const meta = {};
  for (const line of raw.split("\n")) {
    const match = /^([A-Za-z0-9_-]+)\s*:\s*(.*)$/.exec(line.trim());
    if (!match) continue;
    meta[match[1]] = match[2].replace(/^["']|["']$/g, "").trim();
  }
  return { meta, body };
}

function parseTemplateBoolean(value, fallback) {
  if (value == null || value === "") return fallback;
  return /^(true|yes|1|on)$/i.test(String(value).trim());
}

function parseOptionalTemplateBoolean(value) {
  if (value == null || value === "") return null;
  return /^(true|yes|1|on)$/i.test(String(value).trim());
}

function isTaskGenerationTemplate(template = {}) {
  if (template.taskGenerationTemplate != null) return Boolean(template.taskGenerationTemplate);
  const text = `${template.name || ""}\n${template.prompt || ""}`;
  if (!template.createTasks) return false;
  return /\b(todoist-ready task list|generate(?: only)? .*tasks?|follow-up tasks|task extraction)\b/i.test(text) &&
    !/\bsummary\b/i.test(template.name || "");
}

function normalizePromptTemplateAction(value) {
  const action = String(value || "").trim().toLowerCase().replace(/['’]/g, "").replace(/[\s_]+/g, "-");
  if (/^(schedule|schedule-today|schedule-todays-tasks|schedule-today-tasks|schedule-day|plan-today)$/.test(action)) return "schedule-today";
  return action;
}

function isScheduleTodayTemplate(template = {}) {
  return normalizePromptTemplateAction(template.action) === "schedule-today";
}

function promptTemplateFileText(template) {
  return [
    "---",
    ...(template.action ? [`action: ${normalizePromptTemplateAction(template.action)}`] : []),
    `createTasks: ${Boolean(template.createTasks)}`,
    `insertResponse: ${template.insertResponse !== false}`,
    `syncTasks: ${Boolean(template.syncTasks ?? template.syncAfterInsert)}`,
    ...(template.taskGenerationTemplate != null ? [`taskGenerationTemplate: ${Boolean(template.taskGenerationTemplate)}`] : []),
    ...(template.createTasks ? [`taskHeading: '${template.taskHeading || DEFAULT_TASK_HEADING}'`] : []),
    "---",
    "",
    template.prompt || ""
  ].join("\n");
}

function yesNo(value) {
  return value ? "Yes" : "No";
}

function aiProviderCredentialReady(settings = DEFAULT_SETTINGS, provider = "openai") {
  const normalized = normalizeAiProvider(provider);
  if (normalized === "gemini") return Boolean(settings.googleApiKey);
  if (normalized === "openrouter") return Boolean(settings.openrouterApiKey);
  if (normalized === "openwebui") {
    if (!settings.openwebuiBaseUrl) return false;
    return settings.openwebuiAuthMode === "login"
      ? Boolean(settings.openwebuiJwt)
      : Boolean(settings.openwebuiApiKey);
  }
  return Boolean(settings.openaiApiKey);
}

function aiSetupSummary(settings) {
  const operationPrimary = typeof STS_MULTI_PROVIDER !== "undefined"
    ? STS_MULTI_PROVIDER.operationModelReference(settings, "chat-query")?.primary
    : null;
  const provider = operationPrimary?.provider || (typeof STS_MULTI_PROVIDER !== "undefined"
    ? STS_MULTI_PROVIDER.providerForModel(settings.chatModel, settings)
    : aiProviderForModel(settings.chatModel, settings));
  const embeddingProvider = semanticEmbeddingProviderForSettings(settings);
  const keyReady = aiProviderCredentialReady(settings, provider);
  const embeddingReady = aiProviderCredentialReady(settings, embeddingProvider);
  const modelsLoaded = settings.modelsFetchedAt || settings.geminiModelsFetchedAt || settings.openrouterModelsFetchedAt || settings.openwebuiModelsFetchedAt;
  return `${providerDisplayName(provider)} is preferred. Chat key: ${keyReady ? "set" : "missing"}. Embedding key: ${embeddingReady ? "set" : "missing"}. Model list: ${modelsLoaded ? "loaded" : "not loaded"}.`;
}

function aiAccessConfigured(settings) {
  const operationPrimary = typeof STS_MULTI_PROVIDER !== "undefined"
    ? STS_MULTI_PROVIDER.operationModelReference(settings, "chat-query")?.primary
    : null;
  const chatProvider = operationPrimary?.provider || (typeof STS_MULTI_PROVIDER !== "undefined"
    ? STS_MULTI_PROVIDER.providerForModel(settings.chatModel, settings)
    : aiProviderForModel(settings.chatModel, settings));
  const chatReady = aiProviderCredentialReady(settings, chatProvider);
  const embeddingReady = aiProviderCredentialReady(settings, semanticEmbeddingProviderForSettings(settings));
  return chatReady && embeddingReady;
}

function todoistSetupSummary(settings) {
  return `Token: ${settings.todoistToken ? "set" : "missing"}. Project: ${settings.todoistTaskProjectName || "Inbox"}. Loaded projects: ${settings.availableTodoistProjects?.length || 0}.`;
}

function emailSetupSummary(settings) {
  return `Requires AI + Todoist first. Optional Cloudflare Worker URL: ${settings.workerUrl ? "set" : "missing"}. Worker token: ${settings.workerToken ? "set" : "missing"}. Automatic processing: ${settings.autoProcessEmails ? "on" : "off"}. Poll floor: ${MIN_EMAIL_AUTO_POLL_INTERVAL_SECONDS} seconds.`;
}

function externalMcpExportSummary(plugin) {
  const folder = externalMcpExportFolder(plugin.settings);
  const enabled = plugin.settings.externalMcpExportEnabled ? "on" : "off";
  const chunks = Number(plugin.settings.semanticIndexMeta?.chunks || 0);
  const refs = plugin.taskReferenceIndex?.entries?.length || Object.keys(plugin.settings.taskCache || {}).length;
  return `Bridge: ${enabled}. Folder: ${folder}. Existing semantic chunks: ${chunks}. Task cache entries: ${refs}. The bridge writes only pointer files; the external MCP server must read the existing plugin database files.`;
}

async function externalMcpExportFiles(plugin, folder) {
  const generatedAt = deviceTimestamp();
  const manifest = externalMcpBridgeManifest(plugin, folder, generatedAt);
  return [
    { path: `${folder}/${EXTERNAL_MCP_EXPORT_README_FILE}`, body: externalMcpBridgeReadmeMarkdown(manifest) },
    { path: `${folder}/${EXTERNAL_MCP_EXPORT_MANIFEST_FILE}`, body: externalMcpBridgeManifestMarkdown(manifest) },
    { path: `${folder}/bridge-manifest.json`, body: JSON.stringify(manifest, null, 2) }
  ];
}

function externalMcpSemanticIndexPaths(plugin, pluginDir, indexFile) {
  const settings = plugin?.settings && typeof plugin.settings === "object" ? plugin.settings : DEFAULT_SETTINGS;
  const meta = settings.semanticIndexMeta && typeof settings.semanticIndexMeta === "object" ? settings.semanticIndexMeta : {};
  let partition = plugin?.semanticIndexActivePartition;
  if (!partition?.relativeDir && typeof plugin?.semanticIndexStoragePartition === "function") {
    partition = plugin.semanticIndexStoragePartition();
  }
  if (!partition?.relativeDir) {
    partition = semanticIndexPartitionContract(settings, {
      indexFile,
      meta,
      actualDimension: meta.actualDimension || meta.dimension,
      configuredDimension: meta.configuredDimension || meta.targetDimension
    });
  }
  const relativeDir = String(partition?.relativeDir || "").trim();
  if (!relativeDir || relativeDir.split("/").some((part) => !part || part === "." || part === ".." || !/^[a-z0-9._-]+$/i.test(part))) {
    throw new Error("Active semantic-index storage partition is invalid.");
  }
  const pathFor = (file, label) => `${pluginDir}/${relativeDir}/${normalizedPluginBasename(file, label)}`;
  const manifestPath = pathFor(indexFile, "semantic-index manifest");
  const knownShardFiles = uniqueValues(plugin?.semanticIndexKnownShardFiles || []).map((file) => pathFor(file, "semantic-index shard"));
  const pathMetaFile = meta.pathMetaFile || partition?.basenames?.pathMetaFile || SEMANTIC_INDEX_PATH_META_FILE;
  const pathMetaPath = pathFor(pathMetaFile, "semantic-index path metadata");
  const stablePathMetaPath = pathFor(SEMANTIC_INDEX_PATH_META_FILE, "semantic-index path metadata");
  const routingPath = pathFor(partition?.basenames?.routingFile || LOCAL_SEMANTIC_ROUTING_ARTIFACT_FILE, "semantic-index routing artifact");
  return { partition, relativeDir, manifestPath, knownShardFiles, pathMetaPath, stablePathMetaPath, routingPath };
}

function externalMcpBridgeManifest(plugin, folder, generatedAt) {
  const indexFile = plugin.settings.semanticIndexMeta?.file || (plugin.semanticIndexFileName ? plugin.semanticIndexFileName() : SEMANTIC_INDEX_FILE);
  const pluginDir = plugin.manifest?.dir || ".obsidian/plugins/semantic-todoist-sync";
  const taskCount = Object.keys(plugin.settings.taskCache || {}).length;
  const pendingReferenceCount = Object.keys(plugin.settings.pendingTaskReferences || {}).length;
  const liveSnapshot = plugin.todoistSnapshotCache?.snapshot || null;
  const semanticIndexPaths = externalMcpSemanticIndexPaths(plugin, pluginDir, indexFile);
  const knownShardFiles = semanticIndexPaths.knownShardFiles;
  const bridgeFiles = [
    `${folder}/${EXTERNAL_MCP_EXPORT_README_FILE}`,
    `${folder}/${EXTERNAL_MCP_EXPORT_MANIFEST_FILE}`,
    `${folder}/bridge-manifest.json`
  ];
  const pluginDataReadPaths = [
    semanticIndexPaths.manifestPath,
    ...knownShardFiles,
    semanticIndexPaths.pathMetaPath,
    semanticIndexPaths.stablePathMetaPath,
    semanticIndexPaths.routingPath,
    `${pluginDir}/${TASK_REFERENCE_SNAPSHOT_FILE}`,
    `${pluginDir}/${TASK_REFERENCE_INDEX_FILE}`,
    `${pluginDir}/${SCHEDULER_MEMORY_FILE}`
  ];
  return {
    version: 1,
    generatedAt,
    sourcePlugin: plugin.manifest?.id || "semantic-todoist-sync",
    sourcePluginVersion: plugin.manifest?.version || "",
    exportFolder: folder,
    mode: "bridge-manifest-only",
    note: "This hook does not recreate or alter Semantic Todoist Sync databases. It points an external Obsidian MCP server plugin to the existing files maintained by Semantic Todoist Sync.",
    directPluginDataAccessRequired: true,
    databases: {
      semanticIndex: {
        type: "semantic-index-manifest",
        path: semanticIndexPaths.manifestPath,
        partitionRelativeDir: semanticIndexPaths.relativeDir,
        meta: plugin.settings.semanticIndexMeta || {},
        knownShardFiles,
        routingPath: semanticIndexPaths.routingPath,
        access: "Read this manifest first; its shards array names the existing semantic index shard files in the same plugin data directory."
      },
      semanticIndexPathMeta: {
        type: "semantic-index-path-metadata",
        path: semanticIndexPaths.pathMetaPath,
        stablePath: semanticIndexPaths.stablePathMetaPath
      },
      semanticIndexRouting: {
        type: "semantic-index-routing-artifact",
        path: semanticIndexPaths.routingPath
      },
      localReferenceTable: {
        type: "task-reference-snapshot",
        path: `${pluginDir}/${TASK_REFERENCE_SNAPSHOT_FILE}`,
        indexPath: `${pluginDir}/${TASK_REFERENCE_INDEX_FILE}`,
        taskCount,
        pendingReferenceCount,
        jsonPointers: {
          taskCache: "/taskCache",
          pendingTaskReferences: "/pendingTaskReferences",
          pendingTaskDescriptions: "/pendingTaskDescriptions",
          compactIndex: "/index"
        }
      },
      todoistSnapshot: {
        type: "local-cached-todoist-snapshot",
        path: `${pluginDir}/${TASK_REFERENCE_SNAPSHOT_FILE}`,
        jsonPointer: "/taskCache",
        taskCount,
        liveSnapshotCurrentlyCachedInMemory: Boolean(liveSnapshot),
        liveSnapshotResourceTypes: liveSnapshot ? Object.keys(liveSnapshot).filter((key) => Array.isArray(liveSnapshot[key])) : [],
        note: "Semantic Todoist Sync persists the local Todoist task cache in task-reference-snapshot.json. A live Todoist API snapshot is only in memory and is not duplicated by this hook."
      },
      schedulerMemory: {
        type: "scheduler-memory",
        path: `${pluginDir}/${SCHEDULER_MEMORY_FILE}`
      }
    },
    expectedExternalMcpCapabilities: [
      "Read files from this plugin data directory through Obsidian's vault adapter or plugin API.",
      "Allow explicit read access to the Semantic Todoist Sync plugin data directory when the MCP server filters hidden folders by default.",
      "Parse the existing semantic-index manifest and shard files without asking Semantic Todoist Sync to regenerate them.",
      "Parse task-reference-snapshot.json for Todoist task cache, local OID references, pending references, and descriptions."
    ],
    mcpServerAccessProfile: {
      minimumConfiguration: "Enable this bridge in Semantic Todoist Sync, point the external MCP server at the vault root, and allow read-only access to the listed Semantic Todoist Sync plugin data files.",
      discoveryFiles: bridgeFiles,
      requiredReadOnlyPaths: pluginDataReadPaths,
      requiredExtensions: [".md", ".json"],
      stockMcpVaultCompatibility: {
        canDiscoverBridgeFolder: true,
        canReadBridgeMarkdown: true,
        canSearchBridgeMarkdown: true,
        canReadBridgeJson: false,
        canReadPluginDataDirectory: false,
        reason: "MCPVault's default path filter blocks .obsidian, .git, node_modules, and dotfile paths at any depth, and its default note reader excludes .json files."
      },
      mcpVaultCompatibleConfiguration: {
        pathFilter: "Use an imported MCPVault createServer() with a custom read-only PathFilter that allows only discoveryFiles plus requiredReadOnlyPaths.",
        allowedReadPrefixes: [folder, pluginDir],
        blockedWritePrefixes: [pluginDir],
        safeAllowedTools: [
          "read_note",
          "read_multiple_notes",
          "get_notes_info",
          "get_frontmatter",
          "get_vault_stats",
          "list_all_tags",
          "list_directory",
          "search_notes"
        ],
        semanticTodoistTools: [
          "semantic_todoist.search_semantic_index",
          "semantic_todoist.get_todoist_snapshot",
          "semantic_todoist.get_reference_table"
        ],
        mustHideOrGateTools: [
          "write_note",
          "patch_note",
          "update_frontmatter",
          "delete_note",
          "move_note",
          "move_file",
          "manage_tags"
        ],
        chatGptAllowedToolsHint: "Configure the ChatGPT MCP connector or client to expose only safeAllowedTools plus semanticTodoistTools for this bridge. Keep mustHideOrGateTools unavailable or approval-gated.",
        discoveryTools: ["list_directory", "read_note", "read_multiple_notes", "search_notes"],
        note: "MCPVault's built-in search_notes indexes Markdown notes, so semantic-index and Todoist JSON querying should be exposed through the recommended semantic_todoist.* read-only tools.",
        recommendedWriteToolPolicy: "Keep write_note, patch_note, update_frontmatter, delete_note, move_note, and move_file disabled or approval-gated for the Semantic Todoist Sync plugin data directory."
      }
    },
    recommendedReadOnlyTools: externalMcpRecommendedTools()
  };
}

function externalMcpRecommendedTools() {
  return [
    {
      name: "semantic_todoist.search_semantic_index",
      description: "Use this when ChatGPT needs ranked note context from the existing Semantic Todoist Sync semantic index.",
      readOnlyHint: true,
      annotations: { readOnlyHint: true },
      inputSchema: {
        type: "object",
        properties: {
          query: { type: "string", description: "Natural-language search query." },
          limit: { type: "integer", minimum: 1, maximum: 20, default: 8 }
        },
        required: ["query"],
        additionalProperties: false
      },
      outputSchema: {
        type: "object",
        properties: {
          results: {
            type: "array",
            items: {
              type: "object",
              properties: {
                path: { type: "string" },
                title: { type: "string" },
                score: { type: "number" },
                text: { type: "string" },
                chunkId: { type: "string" }
              }
            }
          }
        }
      }
    },
    {
      name: "semantic_todoist.get_todoist_snapshot",
      description: "Use this when ChatGPT needs the local cached Todoist task snapshot already persisted by Semantic Todoist Sync.",
      readOnlyHint: true,
      annotations: { readOnlyHint: true },
      inputSchema: {
        type: "object",
        properties: {
          taskIds: { type: "array", items: { type: "string" }, description: "Optional Todoist task IDs to retrieve from /taskCache." },
          includeCompleted: { type: "boolean", default: false }
        },
        additionalProperties: false
      },
      outputSchema: {
        type: "object",
        properties: {
          tasks: { type: "array", items: { type: "object" } },
          sourcePath: { type: "string" },
          sourcePointer: { type: "string" }
        }
      }
    },
    {
      name: "semantic_todoist.get_reference_table",
      description: "Use this when ChatGPT needs local OID mappings, note references, pending references, or the compact reference index.",
      readOnlyHint: true,
      annotations: { readOnlyHint: true },
      inputSchema: {
        type: "object",
        properties: {
          oids: { type: "array", items: { type: "string" }, description: "Optional Semantic Todoist Sync OIDs to retrieve." },
          includePending: { type: "boolean", default: true }
        },
        additionalProperties: false
      },
      outputSchema: {
        type: "object",
        properties: {
          entries: { type: "array", items: { type: "object" } },
          pendingTaskReferences: { type: "object" },
          pendingTaskDescriptions: { type: "object" },
          sourcePath: { type: "string" },
          indexPath: { type: "string" }
        }
      }
    }
  ];
}

