const stsMpOperationName = (operation = "chat") => {
  const value = String(operation || "chat").toLowerCase();
  if (["chat", "chat-query", "query"].includes(value)) return "chat-query";
  if (["description", "task-description"].includes(value)) return "task-description";
  if (["section-title", "section"].includes(value)) return "section-title";
  if (["task-generation", "task", "tasks"].includes(value)) return "task-generation";
  if (["scheduler", "schedule", "scheduler-duration"].includes(value)) return "scheduler";
  if (["policy", "dedupe-policy"].includes(value)) return "policy";
  if (["deduplication", "dedupe"].includes(value)) return "deduplication";
  if (["prompt-response", "prompt", "response"].includes(value)) return "prompt-response";
  return STS_MULTI_PROVIDER.OPERATION_KEYS.includes(value) ? value : "prompt-response";
};

if (typeof module !== "undefined" && module.exports?.prototype) {
  const stsMpPluginPrototype = module.exports.prototype;

  stsMpPluginPrototype.recordDebugDiagnostic = function(value = {}) {
    if (this.settings?.debugDiagnosticsEnabled !== true) {
      if (Array.isArray(this._debugDiagnosticRing)) this._debugDiagnosticRing.length = 0;
      return null;
    }
    if (!Array.isArray(this._debugDiagnosticRing)) this._debugDiagnosticRing = [];
    const record = aiGatewayDebugDiagnosticRecord(value);
    if (this._debugDiagnosticRing.length >= AI_DEBUG_DIAGNOSTIC_CAPACITY) {
      this._debugDiagnosticRing.splice(0, this._debugDiagnosticRing.length - AI_DEBUG_DIAGNOSTIC_CAPACITY + 1);
    }
    this._debugDiagnosticRing.push(record);
    return record;
  };

  stsMpPluginPrototype.getDebugDiagnosticSnapshot = function() {
    if (this.settings?.debugDiagnosticsEnabled !== true) {
      if (Array.isArray(this._debugDiagnosticRing)) this._debugDiagnosticRing.length = 0;
      return { enabled: false, capacity: AI_DEBUG_DIAGNOSTIC_CAPACITY, count: 0, events: [] };
    }
    const events = (Array.isArray(this._debugDiagnosticRing) ? this._debugDiagnosticRing : []).slice(-AI_DEBUG_DIAGNOSTIC_CAPACITY);
    return { enabled: true, capacity: AI_DEBUG_DIAGNOSTIC_CAPACITY, count: events.length, events };
  };

  stsMpPluginPrototype.clearDebugDiagnostics = function() {
    const cleared = Array.isArray(this._debugDiagnosticRing) ? this._debugDiagnosticRing.length : 0;
    this._debugDiagnosticRing = [];
    return cleared;
  };

  stsMpPluginPrototype.aiModelForRequest = function(mode, options = {}) {
    const operation = stsMpOperationName(mode);
    const reference = STS_MULTI_PROVIDER.operationModelReference(this.settings, operation);
    const primary = reference?.primary || {
      provider: normalizeAiProvider(this.settings.aiModelProvider, aiProviderForModel(this.settings.chatModel, this.settings)),
      model: this.settings.chatModel || DEFAULT_SETTINGS.chatModel
    };
    return {
      model: primary.model,
      provider: primary.provider,
      primaryModel: primary.model,
      fallbackModel: reference?.fallback?.model || "",
      fallbackProvider: reference?.fallback?.provider || "",
      strongModel: "",
      useStrong: false,
      score: 0,
      signals: {},
      reasons: []
    };
  };

  stsMpPluginPrototype.loginOpenWebUI = async function(email, ephemeralPassword) {
    const normalized = STS_MULTI_PROVIDER.normalizeOpenWebUISettings(this.settings, this.settings);
    Object.assign(this.settings, normalized);
    const auth = STS_MULTI_PROVIDER.openWebUIAuth(this.settings, { requestUrl: typeof requestUrl === "function" ? requestUrl : null, previous: normalized });
    const result = await auth.login({ email, password: ephemeralPassword });
    Object.assign(this.settings, result.settingsPatch);
    await this.saveSettings();
    return { expiresAt: result.expiresAt, tokenType: result.tokenType };
  };

  stsMpPluginPrototype.openWebUIAuthStatus = function() {
    const auth = STS_MULTI_PROVIDER.openWebUIAuth(this.settings, { requestUrl: typeof requestUrl === "function" ? requestUrl : null });
    return { baseUrl: auth.state.baseUrl, authMode: auth.state.authMode, authIdentityHash: auth.state.identityHash, authenticated: auth.isAuthenticated(), expiresAt: auth.state.expiresAt };
  };

  stsMpPluginPrototype.postOpenWebUICapabilityObservationMessage = async function(record = {}) {
    const model = STS_MULTI_PROVIDER.normalizeModel("openwebui", record.model || "");
    if (!model) return false;
    const operation = STS_MULTI_PROVIDER.openWebUIAdaptiveOperation(record.operation || "");
    const operationLabel = ({
      "chat-query": "Chat",
      "task-description": "Task descriptions",
      "task-generation": "Task generation"
    })[operation] || operation;
    const carrierLabel = ({
      "direct-schema": "Native JSON Schema",
      "direct-json": "JSON mode",
      "wrapper-json": "Wrapped JSON"
    })[record.preferredCarrier || record.successfulCarrier] || "Provider carrier";
    const message = `Saved OpenWebUI profile · ${model} · ${operationLabel} · ${carrierLabel}.`;
    try {
      if (!this.app?.workspace?.getLeavesOfType) return false;
      await this.openSidebar();
      const view = this.app.workspace.getLeavesOfType(VIEW_TYPE)[0]?.view;
      if (!view || typeof view.addMessage !== "function") return false;
      view.addMessage("assistant", message);
      return true;
    } catch (error) {
      try { this.logLocal?.("OpenWebUI profile chat message skipped", { error: error?.message || String(error) }); } catch {}
      return false;
    }
  };

  stsMpPluginPrototype.deleteOpenWebUICapabilityProfile = async function(profile = {}, operationOverride = "") {
    const input = typeof profile === "string" ? { model: profile, operation: operationOverride } : profile || {};
    const keyParts = String(input.key || "").split("|");
    const model = STS_MULTI_PROVIDER.normalizeModel("openwebui", input.model || keyParts[1] || "");
    const operation = STS_MULTI_PROVIDER.openWebUIAdaptiveOperation(input.operation || keyParts[2] || "");
    if (!model || !operation || typeof STS_MULTI_PROVIDER.openWebUIDeleteSingletonDescriptionCapability !== "function") return false;
    const changed = STS_MULTI_PROVIDER.openWebUIDeleteSingletonDescriptionCapability(model, operation, this.settings);
    if (!changed) return false;
    const persist = async () => this.saveSettings({
      skipTaskReferenceSnapshot: true,
      writeKind: "provider-derived-metadata",
      provider: "openwebui",
      changedKeys: ["openwebuiModelMetadata"]
    });
    const pending = Promise.resolve(this._openWebUICapabilityPersistence).catch(() => null).then(persist);
    this._openWebUICapabilityPersistence = pending;
    try {
      await pending;
    } finally {
      if (this._openWebUICapabilityPersistence === pending) this._openWebUICapabilityPersistence = null;
    }
    return true;
  };

  stsMpPluginPrototype.recordOpenWebUICapabilityObservation = async function(observation = {}) {
    if (!observation || typeof observation !== "object") return false;
    const model = STS_MULTI_PROVIDER.normalizeModel("openwebui", observation.model || "");
    const operation = String(observation.operation || "").trim().toLowerCase();
    const carrier = String(observation.successfulCarrier || observation.preferredCarrier || "").trim();
    const adaptiveConcurrencyLimit = Number(observation.adaptiveConcurrencyLimit ?? observation.effectiveConcurrencyLimit);
    const adaptiveObservation = Number.isSafeInteger(adaptiveConcurrencyLimit)
      && adaptiveConcurrencyLimit >= 1
      && adaptiveConcurrencyLimit <= 4;
    if (!model || !operation || (!adaptiveObservation && !["direct-schema", "direct-json", "wrapper-json"].includes(carrier))) return false;
    const before = JSON.stringify(this.settings?.openwebuiModelMetadata?.[model]?.structuredCapabilityProfiles || {});
    const record = STS_MULTI_PROVIDER.openWebUIRecordSingletonDescriptionCapability(model, Object.assign({}, observation, {
      provider: "openwebui",
      operation,
      ...(carrier ? { successfulCarrier: carrier } : {}),
      settings: this.settings
    }));
    if (!record) return false;
    const changed = before !== JSON.stringify(this.settings?.openwebuiModelMetadata?.[model]?.structuredCapabilityProfiles || {});
    if (changed) {
      let persisted = false;
      const persist = async () => {
        try {
          await this.saveSettings({
            skipTaskReferenceSnapshot: true,
            writeKind: "provider-derived-metadata",
            provider: "openwebui",
            changedKeys: ["openwebuiModelMetadata"]
          });
          persisted = true;
        } catch {}
      };
      const pending = Promise.resolve(this._openWebUICapabilityPersistence).catch(() => null).then(persist);
      this._openWebUICapabilityPersistence = pending;
      try { await pending; } finally {
        if (this._openWebUICapabilityPersistence === pending) this._openWebUICapabilityPersistence = null;
      }
      if (persisted) await this.postOpenWebUICapabilityObservationMessage(record);
    }
    return changed;
  };

}

